from typing import List

def min_booked_time(N: int, M: int, trains: List[List[int]]) -> int:
    def can_book_at(time):
        current_time = time
        for i in range(M):
            X, S, T, L = trains[i]
            if X == 1:
                if current_time + L >= T:
                    return False
                current_time += L
            else:
                if current_time + L >= T:
                    return False
                current_time += L
        return True

    left, right = 0, 86400
    while left < right:
        mid = (left + right) // 2
        if can_book_at(mid):
            right = mid
        else:
            left = mid + 1
    return left if can_book_at(left) else "impossible"

